*** Begin Patch
*** Update File: /app/internal/opa/rule/rule.go
@@
 import (
 	"fmt"
 	"regexp"
 	"strings"
+	"time"

 	"github.com/open-policy-agent/opa/ast"
 )
@@
 func effectiveOn(a *ast.AnnotationsRef) string {
-	return customAnnotationString(a, "effective_on")
+	if a == nil || a.Annotations == nil || a.Annotations.Custom == nil {
+		return ""
+	}
+	switch value := a.Annotations.Custom["effective_on"].(type) {
+	case string:
+		return value
+	case time.Time:
+		return value.UTC().Format(time.RFC3339)
+	default:
+		return ""
+	}
 }
*** End Patch
